inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "flux2-klein/outpaint",
  "label": {
    "en": "Outpaint",
    "ru": "Расширение кадра"
  },
  "family": "flux2-klein",
  "family_label": "Flux 2 Klein",
  "tier": 2,
  "mode": "outpaint",
  "order": 10,
  "requires": [
    "source_image"
  ],
  "controls": [
    {
      "param": "frame",
      "kind": "choice",
      "label": {
        "en": "New frame",
        "ru": "Новый кадр"
      },
      "options": [
        {
          "value": "21:9",
          "label": "21:9"
        },
        {
          "value": "16:9",
          "label": "16:9"
        },
        {
          "value": "3:2",
          "label": "3:2"
        },
        {
          "value": "4:3",
          "label": "4:3"
        },
        {
          "value": "1:1",
          "label": "1:1"
        },
        {
          "value": "3:4",
          "label": "3:4"
        },
        {
          "value": "2:3",
          "label": "2:3"
        },
        {
          "value": "9:16",
          "label": "9:16"
        },
        {
          "value": "9:21",
          "label": "9:21"
        }
      ],
      "default": "16:9",
      "open": true
    },
    {
      "param": "megapixels",
      "kind": "slider",
      "min": 0.5,
      "max": 4.0,
      "step": 0.1,
      "default": 1.5,
      "label": {
        "en": "Result size",
        "ru": "Размер результата"
      },
      "unit": "MP"
    },
    {
      "param": "seed",
      "kind": "seed"
    }
  ],
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "flux.?2.?klein.*(9b|4b)|ArtiusFlux"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen_3_(8b|4b)"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "flux2-vae"
    }
  ]
}
